-- ============================================================================
-- Provas oficiais 2018–2026: cadernos e gabaritos (ENEM, FUVEST, UNICAMP, ITA, IME, UNESP)
--
-- Mesmo modelo do ENEM 2025: só o ENDEREÇO fica no Nexa; o arquivo continua no site oficial.
-- Caderno e gabarito da mesma prova usam o MESMO rótulo (ENEM: "1º dia · Caderno 2 · Amarelo"), e é assim que o app os
-- liga (dia + cor). Os gabaritos lidos do PDF vão em exam_answer_keys com o caderno (variant) igual ao do ENEM/UNICAMP:
-- o aluno escolhe a cor e é corrigido pelo gabarito dela. Nada é sobrescrito: o que o administrador já cadastrou vale.
-- Nas questões 1 a 5 do ENEM vale a resposta de INGLÊS (a coluna de espanhol não entra: o cartão tem uma letra por número).
-- Questão anulada vale como certa para todos (regra do cartão-resposta).
-- Ano = ano do vestibular na linguagem da banca (FUVEST, UNICAMP, UNESP, ITA e IME pelo ano de ingresso; ENEM pelo ano da prova).
-- ============================================================================

insert into public.exam_editions (exam_id, year, label)
select e.id, y.year, e.name || ' ' || y.year
from public.exams e
cross join generate_series(2017, 2026) as y(year)
where e.slug in ('enem', 'fuvest', 'unicamp', 'unesp', 'ita', 'ime')
on conflict (exam_id, year) do nothing;

