-- Uma linha por caderno: as letras em sequência a partir do número inicial ('*' = anulada).
insert into public.exam_answer_keys (exam_edition_id, variant, number, correct, annulled, area)
select ee.id, v.variant, v.start_no + g.i - 1,
       case when c.ch = '*' then null else c.ch end,
       c.ch = '*',
       case when v.area_kind = 'enem' then
         case when v.start_no + g.i - 1 <= 45 then 'Linguagens'
              when v.start_no + g.i - 1 <= 90 then 'Ciências Humanas'
              when v.start_no + g.i - 1 <= 135 then 'Ciências da Natureza'
              else 'Matemática' end
       end
