join public.exam_editions ee on ee.exam_id = e.id and ee.year = v.year
cross join lateral generate_series(1, length(v.answers)) as g(i)
cross join lateral (select substr(v.answers, g.i, 1) as ch) as c
on conflict (exam_edition_id, variant, number) do nothing;

